package com.pocketmemory.app;

import android.app.*;
import android.content.*;
import android.graphics.Bitmap;
import android.net.Uri;
import android.provider.MediaStore;
import android.view.WindowManager;
import android.widget.*;
import java.io.File;
import java.util.*;

public final class PhotoUi {
    final MainActivity a;final MemoryApp app;boolean hindi=false;
    PhotoUi(MainActivity a){this.a=a;app=a.app;}
    void choose(){new ThemedDialog.Builder(a).setTitle("Keep a photo and its words").setItems(new String[]{"Take a photo","Choose a photo","OCR language: "+(hindi?"Hindi / Devanagari":"English / Latin")},(d,i)->{if(i==0)capture();if(i==1)a.pick(MainActivity.PICK_PHOTO,"image/*");if(i==2)new ThemedDialog.Builder(a).setTitle("Text in the photo").setSingleChoiceItems(new String[]{"English / Latin","Hindi / Devanagari"},hindi?1:0,(x,w)->{hindi=w==1;x.dismiss();choose();}).show();}).show();}
    void capture(){String name=LifeStore.id()+".jpg";Uri uri=PhotoProvider.uri(a,name);Intent camera=new Intent(MediaStore.ACTION_IMAGE_CAPTURE).putExtra(MediaStore.EXTRA_OUTPUT,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);camera.setClipData(ClipData.newRawUri("Photo capture",uri));try{app.getSharedPreferences("capture",0).edit().putString("pending",name).apply();a.startActivityForResult(camera,MainActivity.CAPTURE_PHOTO);}catch(ActivityNotFoundException e){app.getSharedPreferences("capture",0).edit().remove("pending").apply();a.toast("No camera app is installed. You can choose an existing photo.");}}
    void captured(boolean success){String name=app.getSharedPreferences("capture",0).getString("pending","");app.getSharedPreferences("capture",0).edit().remove("pending").apply();if(name.isBlank())return;File file=PhotoProvider.capture(a,name);if(success&&file.isFile()){importPhoto(PhotoProvider.uri(a,name),()->{a.revokeUriPermission(PhotoProvider.uri(a,name),Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);file.delete();});}else file.delete();}
    void importPhoto(Uri uri,Runnable done){if(app.ocrBusy){a.toast("One photo is being processed. Please wait.");done.run();return;}app.ocrBusy=true;app.workStatus="Reading the photo on this phone…";app.changed();boolean script=hindi;app.files.execute(()->{PhotoStore.Photo photo=null;try{photo=PhotoStore.importPhoto(a,uri);try{photo.text=PhotoStore.recognize(a,photo.filename,script);}catch(Exception error){PhotoStore.Photo keep=photo;app.main.post(()->a.toast("The photo is kept. Text recognition did not finish; you can type a description."));}PhotoStore.Photo ready=photo;app.main.post(()->{if(!a.destroyed)review(ready);else PhotoStore.file(a,ready.filename).delete();});}catch(Exception|OutOfMemoryError error){if(photo!=null)PhotoStore.file(a,photo.filename).delete();app.main.post(()->a.toast(MainActivity.friendly(error)));}finally{done.run();app.ocrBusy=false;app.workStatus="";app.changed();}});}
    boolean hasDraft(){try{String name=new org.json.JSONObject(app.getSharedPreferences("photo_draft",0).getString("photo","{}")).optString("filename");return !name.isEmpty()&&PhotoStore.file(a,name).isFile();}catch(Exception e){return false;}}
    void resumeDraft(){try{org.json.JSONObject j=new org.json.JSONObject(app.getSharedPreferences("photo_draft",0).getString("photo","{}"));PhotoStore.Photo p=new PhotoStore.Photo();p.id=j.getString("id");p.filename=j.getString("filename");p.text=j.optString("text");p.width=j.getInt("width");p.height=j.getInt("height");review(p);}catch(Exception e){a.toast("This scan draft is no longer available.");}}
    void review(PhotoStore.Photo photo){
        try{app.getSharedPreferences("photo_draft",0).edit().putString("photo",new org.json.JSONObject().put("id",photo.id).put("filename",photo.filename).put("text",photo.text).put("width",photo.width).put("height",photo.height).toString()).apply();}catch(Exception ignored){}

        LinearLayout form=a.column();form.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(18));Bitmap preview=PhotoStore.thumbnail(a,photo.filename,900);ImageView image=new ImageView(a);image.setImageBitmap(preview);image.setScaleType(ImageView.ScaleType.CENTER_CROP);form.addView(image,new LinearLayout.LayoutParams(-1,a.dp(180)));a.gap(form,12);EditText title=a.input("Photo title",false);title.setText("Photo · "+LifeStore.today());a.add(form,title);a.limit(form,title,InputLimits.TITLE);a.gap(form,10);a.add(form,a.text("Review names and numbers before saving. Photo OCR runs on this phone; its SDK may send diagnostic metrics when online (details in Settings).",12,MainActivity.MUTED));a.gap(form,8);EditText words=a.input("Text from the photo, or your own description",true);words.setId(R.id.ocr_text);words.setMinLines(5);words.setText(photo.text);a.add(form,words);a.limit(form,words,InputLimits.NOTE);a.gap(form,12);boolean[] saved={false};Dialog[] dialog={null};Button save=a.button("Save photo + memory",true,()->{String text=words.getText().toString().trim();if(text.isBlank())text="Photo saved: "+title.getText().toString();a.saveReviewed(null,title.getText().toString(),text,"Text reviewed from a photo",0,dialog[0],id->{PhotoStore.attach(app.store,id,photo);saved[0]=true;app.getSharedPreferences("photo_draft",0).edit().clear().apply();});});save.setId(R.id.ocr_save);a.add(form,save);new SplitUi(a).option(form,words,()->title.getText().toString(),()->"Text reviewed from a photo",0,()->dialog[0],id->PhotoStore.attach(app.store,id,photo),()->{saved[0]=true;app.getSharedPreferences("photo_draft",0).edit().clear().apply();});ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog alert=new ThemedDialog.Builder(a).setTitle("A photo, remembered").setView(scroll).setNegativeButton("Cancel",null).create();dialog[0]=alert;a.featureDialog=alert;alert.setOnDismissListener(d->{if(!saved[0]&&!a.destroyed){PhotoStore.file(a,photo.filename).delete();app.getSharedPreferences("photo_draft",0).edit().clear().apply();}if(preview!=null)preview.recycle();});alert.show();alert.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
    }
    void view(long note){List<org.json.JSONObject> photos=PhotoStore.forNote(app.store,note);if(photos.isEmpty())return;String[] labels=new String[photos.size()];for(int i=0;i<labels.length;i++)labels[i]="Photo "+(i+1)+" · "+a.date(photos.get(i).optLong("created"));if(photos.size()==1)viewPhoto(photos.get(0));else new ThemedDialog.Builder(a).setTitle("Saved photos").setItems(labels,(d,i)->viewPhoto(photos.get(i))).show();}
    void viewPhoto(org.json.JSONObject photo){Bitmap bitmap=PhotoStore.thumbnail(a,photo.optString("filename"),1600);ImageView image=new ImageView(a);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);ScrollView scroll=new ScrollView(a);scroll.addView(image);AlertDialog dialog=new ThemedDialog.Builder(a).setTitle("Saved on this phone").setView(scroll).setPositiveButton("Close",null).create();dialog.setOnDismissListener(d->{if(bitmap!=null)bitmap.recycle();});dialog.show();}
}
